#!/usr/bin/env node
/*
 * Creates the eight Producer Magazine articles as scheduled Ghost posts and
 * adds reciprocal links to the relevant live cornerstones. Run --dry-run
 * before --apply. The script is deliberately idempotent by slug and marker.
 */
const jwt = require('jsonwebtoken');
require('./load-env');

const BASE = process.env.GHOST_URL;
const ID = process.env.GHOST_ADMIN_KEY_ID;
const SECRET = process.env.GHOST_ADMIN_KEY_SECRET;
const APPLY = process.argv.includes('--apply');
const MARK = '<!-- producer-magazine-2026 -->';

function token() { return jwt.sign({}, Buffer.from(SECRET, 'hex'), { keyid: ID, algorithm: 'HS256', expiresIn: '5m', audience: '/admin/' }); }
async function api(method, endpoint, data) {
  const res = await fetch(`${BASE}/ghost/api/admin/${endpoint}`, { method, headers: { Authorization: `Ghost ${token()}`, 'Content-Type': 'application/json' }, body: data ? JSON.stringify(data) : undefined });
  if (!res.ok) throw new Error(`${method} ${endpoint}: ${res.status} ${await res.text()}`);
  return res.json();
}
function lexical(markdown) { return JSON.stringify({ root: { children: [{ type: 'markdown', version: 1, markdown }], direction: null, format: '', indent: 0, type: 'root', version: 1 } }); }
function dateET(day) { return `${day}T14:00:00.000Z`; } // 10:00 AM EDT / America/Toronto
function link(slug, title) { return `[${title}](https://blog.beatpass.ca/${slug}/)`; }
function words(text) { return text.replace(/https?:\/\/\S+/g, '').split(/\s+/).filter(Boolean).length; }

