async function main() {
  const all = await api('GET', 'posts/?limit=all&status=all&include=tags&formats=lexical');
  const bySlug = new Map((all.posts || []).map(p => [p.slug, p]));
  for (const a of articles) {
    const markdown = render(a);
    if (words(markdown) < 1800) throw new Error(`${a.slug} is only ${words(markdown)} words`);
    if (bySlug.has(a.slug)) { console.log(`SKIP existing ${a.slug}`); continue; }
    console.log(`${APPLY ? 'CREATE' : 'PLAN  '} ${a.day} ${a.slug} (${words(markdown)} words)`);
    if (APPLY) await api('POST', 'posts/', { posts: [{ title: a.title, slug: a.slug, lexical: lexical(markdown), meta_title: a.metaTitle, meta_description: a.meta, custom_excerpt: a.excerpt, tags: a.tags.map(name => ({ name })), status: 'scheduled', published_at: dateET(a.day) }] });
  }
  for (const [slug, sentence] of reciprocal) {
    const post = bySlug.get(slug); if (!post) throw new Error(`missing reciprocal source ${slug}`);
    const doc = JSON.parse(post.lexical); const card = doc.root.children.find(n => n.type === 'markdown');
    if (!card || typeof card.markdown !== 'string') throw new Error(`${slug} does not have a Markdown card`);
    if (card.markdown.includes(sentence)) { console.log(`SKIP linked ${slug}`); continue; }
    const at = card.markdown.indexOf('## Next reads'); if (at < 0) throw new Error(`${slug} has no Next reads`);
    card.markdown = `${card.markdown.slice(0, at).trimEnd()}\n\n${MARK}\n\n${sentence}\n\n${card.markdown.slice(at)}`;
    console.log(`${APPLY ? 'LINK  ' : 'PLAN  '} ${slug}`);
    if (APPLY) await api('PUT', `posts/${post.id}/`, { posts: [{ lexical: JSON.stringify(doc), updated_at: post.updated_at }] });
  }
  const hub = bySlug.get('beatstars-vs-airbit-vs-traktrain-vs-beatpass-platform-comparison-for-producers');
  if (!hub) throw new Error('four-platform hub missing');
  const doc = JSON.parse(hub.lexical); const card = doc.root.children.find(n => n.type === 'markdown');
  const route = `${MARK}\n\n## Where to go next\n\n- ${shared.subscriptions}\n- ${shared.payouts}\n- ${link('how-to-verify-beat-licenses', 'How to Verify Beat Licenses')}\n- ${link('how-to-build-a-beat-catalog-that-sells', 'How to Build a Beat Catalog That Sells')}`;
  if (card) {
    if (!card.markdown.includes(MARK)) { card.markdown = `${card.markdown.trimEnd()}\n\n---\n\n${route}\n`; console.log(`${APPLY ? 'LINK  ' : 'PLAN  '} four-platform hub`); if (APPLY) await api('PUT', `posts/${hub.id}/`, { posts: [{ lexical: JSON.stringify(doc), updated_at: hub.updated_at }] }); }
  } else if (!JSON.stringify(doc).includes('Where to go next')) {
    const text = value => ({ detail: 0, format: 0, mode: 'normal', style: '', text: value, type: 'text', version: 1 });
    const paragraph = children => ({ children, direction: null, format: '', indent: 0, type: 'paragraph', version: 1 });
    const heading = value => ({ children: [text(value)], direction: null, format: '', indent: 0, tag: 'h2', type: 'heading', version: 1 });
    const routeNode = (label, url) => ({ children: [text(label)], direction: null, format: '', indent: 0, rel: null, target: null, title: null, type: 'link', url, version: 1 });
    doc.root.children.push(heading('Where to go next'), paragraph([routeNode('Best Beat Subscription Services in 2026', 'https://blog.beatpass.ca/best-beat-subscription-services-2026/')]), paragraph([routeNode('How Beat Subscription Payouts Work', 'https://blog.beatpass.ca/how-beat-subscription-payouts-work-for-producers/')]), paragraph([routeNode('How to Verify Beat Licenses', 'https://blog.beatpass.ca/how-to-verify-beat-licenses/')]), paragraph([routeNode('How to Build a Beat Catalog That Sells', 'https://blog.beatpass.ca/how-to-build-a-beat-catalog-that-sells/')]));
    console.log(`${APPLY ? 'LINK  ' : 'PLAN  '} four-platform hub`); if (APPLY) await api('PUT', `posts/${hub.id}/`, { posts: [{ lexical: JSON.stringify(doc), updated_at: hub.updated_at }] });
  }
  console.log(APPLY ? 'Applied Producer Magazine plan.' : 'Dry run complete. Use --apply to write.');
}
